import json
from collections import OrderedDict

path = "events.jsonl"
events = []
with open(path, "r", encoding="utf-8") as f:
    for line in f:
        line = line.strip()
        if line:
            events.append(json.loads(line))

events.sort(key=lambda e: (e["seq"], e["msg_id"]))

orders = OrderedDict()
seen = set()
anomalies = []

def log(kind, e):
    anomalies.append({
        "type": kind,
        "msg_id": e["msg_id"],
        "order_id": e["order_id"],
        "seq": e["seq"],
    })

for e in events:
    mid = e["msg_id"]
    if mid in seen:
        log("duplicate_msg_id", e)
        continue
    seen.add(mid)

    if e["amount"] < 0:
        log("negative_amount", e)
        continue

    oid = e["order_id"]
    op = e["op"]
    late_cancel = False

    if op == "create":
        if oid not in orders:
            orders[oid] = {"order_id": oid, "state": "created",
                           "paid_total": 0, "refunded_total": 0}
    elif op == "pay":
        o = orders.get(oid)
        if o is not None and o["state"] in ("created", "paid"):
            o["paid_total"] += e["amount"]
            o["state"] = "paid"
    elif op == "cancel":
        o = orders.get(oid)
        if o is not None:
            if o["state"] == "created":
                o["state"] = "cancelled"
            elif o["state"] in ("paid", "refunded"):
                late_cancel = True
            # cancelled: do nothing
    elif op == "refund":
        o = orders.get(oid)
        if o is not None and o["state"] in ("paid", "refunded"):
            o["refunded_total"] += e["amount"]
            if o["refunded_total"] >= o["paid_total"]:
                o["state"] = "refunded"
            else:
                o["state"] = "paid"

    # precedence: duplicate > negative > unacked > late_cancel
    if not e["ack"]:
        log("unacked", e)
    elif late_cancel:
        log("late_cancel", e)

anomalies.sort(key=lambda a: (a["seq"], a["msg_id"]))

final_state = sorted(orders.values(), key=lambda o: o["order_id"])

with open("final_state.json", "w", encoding="utf-8") as f:
    json.dump(final_state, f, ensure_ascii=False, indent=2)
    f.write("\n")

with open("anomalies.json", "w", encoding="utf-8") as f:
    json.dump(anomalies, f, ensure_ascii=False, indent=2)
    f.write("\n")

print("events:", len(events), "orders:", len(final_state), "anomalies:", len(anomalies))
